//! Editor Attributes Registry
//!
//! A data-driven database of KAIN editor attributes (@slate, @details, @viewport, etc.)
//! and their corresponding UE5 code generation patterns.
//!
//! Loaded from `unreal/metadata/editor_attributes.json` which is generated by
//! the editor_attributes_extractor.py script that scans UE5 engine source.
//!
//! This replaces hardcoded EDITOR_ATTRIBUTES arrays with a queryable registry
//! that can be extended without recompiling the compiler.

use std::collections::HashMap;
use serde::{Deserialize, Serialize};

// ═══════════════════════════════════════════════════════════════════
// Schema Types (mirrors editor_attributes.json structure)
// ═══════════════════════════════════════════════════════════════════

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct NamingConvention {
    #[serde(default)]
    pub prefix: String,
    #[serde(default)]
    pub suffix: String,
    #[serde(default)]
    pub pattern: String,
    // Viewport-specific
    #[serde(default)]
    pub viewport_prefix: String,
    #[serde(default)]
    pub viewport_suffix: String,
    #[serde(default)]
    pub client_prefix: String,
    #[serde(default)]
    pub client_suffix: String,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct BoilerplateFlags {
    #[serde(default)]
    pub slate_begin_args: bool,
    #[serde(default)]
    pub slate_end_args: bool,
    #[serde(default)]
    pub construct_method: bool,
    #[serde(default)]
    pub customize_details_method: bool,
    #[serde(default)]
    pub detail_layout_builder: bool,
    #[serde(default)]
    pub init_editor_method: bool,
    #[serde(default)]
    pub toolkit_name_methods: bool,
    #[serde(default)]
    pub register_tab_spawners: bool,
    #[serde(default)]
    pub startup_module_method: bool,
    #[serde(default)]
    pub shutdown_module_method: bool,
    #[serde(default)]
    pub implement_module_macro: bool,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ExampleInfo {
    pub name: String,
    pub header: String,
    pub module: String,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct AttributeInfo {
    pub description: String,
    pub base_class: String,
    #[serde(default)]
    pub class_prefix: String,
    #[serde(default)]
    pub class_suffix: String,
    pub generates: String,
    #[serde(default)]
    pub required_includes: Vec<String>,
    #[serde(default)]
    pub required_modules: Vec<String>,
    #[serde(default)]
    pub examples: Vec<ExampleInfo>,
    #[serde(default)]
    pub naming_convention: Option<NamingConvention>,
    #[serde(default)]
    pub boilerplate: Option<BoilerplateFlags>,
    // Viewport-specific
    #[serde(default)]
    pub requires_client: bool,
    #[serde(default)]
    pub client_base: String,
    #[serde(default)]
    pub client_prefix: String,
    #[serde(default)]
    pub client_suffix: String,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct MetaInfo {
    pub generator: String,
    pub source: String,
    pub total_attributes: usize,
    pub description: String,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct EditorAttributesData {
    #[serde(rename = "_meta")]
    pub meta: MetaInfo,
    pub attributes: HashMap<String, AttributeInfo>,
}

// ═══════════════════════════════════════════════════════════════════
// Editor Attributes Registry — the queryable runtime database
// ═══════════════════════════════════════════════════════════════════

#[derive(Debug, Clone)]
pub struct EditorAttributesRegistry {
    pub attributes: HashMap<String, AttributeInfo>,
    pub meta: Option<MetaInfo>,
}

impl Default for EditorAttributesRegistry {
    fn default() -> Self {
        Self::new()
    }
}

impl EditorAttributesRegistry {
    pub fn new() -> Self {
        Self {
            attributes: HashMap::new(),
            meta: None,
        }
    }

    /// Load editor attributes from JSON data
    pub fn load(&mut self, json_data: &str) -> Result<(), String> {
        let data: EditorAttributesData = serde_json::from_str(json_data)
            .map_err(|e| format!("Failed to parse editor_attributes.json: {}", e))?;

        self.attributes = data.attributes;
        self.meta = Some(data.meta);
        Ok(())
    }

    // ═══════════════════════════════════════════════════════════════
    // Query API
    // ═══════════════════════════════════════════════════════════════

    /// Check if an attribute name is a known editor attribute
    pub fn is_editor_attribute(&self, name: &str) -> bool {
        self.attributes.contains_key(name)
    }

    /// Get attribute info by name
    pub fn get_attribute(&self, name: &str) -> Option<&AttributeInfo> {
        self.attributes.get(name)
    }

    /// Get the base class for an attribute
    pub fn get_base_class(&self, name: &str) -> Option<&str> {
        self.attributes.get(name).map(|a| a.base_class.as_str())
    }

    /// Get the class prefix for an attribute (e.g., "S" for slate, "F" for details)
    pub fn get_class_prefix(&self, name: &str) -> Option<&str> {
        self.attributes.get(name)
            .map(|a| a.class_prefix.as_str())
            .filter(|s| !s.is_empty())
    }

    /// Get the class suffix for an attribute (e.g., "DetailsCustomization" for details)
    pub fn get_class_suffix(&self, name: &str) -> Option<&str> {
        self.attributes.get(name)
            .map(|a| a.class_suffix.as_str())
            .filter(|s| !s.is_empty())
    }

    /// Get required includes for an attribute
    pub fn get_required_includes(&self, name: &str) -> Vec<&str> {
        self.attributes.get(name)
            .map(|a| a.required_includes.iter().map(|s| s.as_str()).collect())
            .unwrap_or_default()
    }

    /// Get required modules for an attribute
    pub fn get_required_modules(&self, name: &str) -> Vec<&str> {
        self.attributes.get(name)
            .map(|a| a.required_modules.iter().map(|s| s.as_str()).collect())
            .unwrap_or_default()
    }

    /// Get the naming convention for an attribute
    pub fn get_naming_convention(&self, name: &str) -> Option<&NamingConvention> {
        self.attributes.get(name)
            .and_then(|a| a.naming_convention.as_ref())
    }

    /// Get boilerplate flags for an attribute
    pub fn get_boilerplate(&self, name: &str) -> Option<&BoilerplateFlags> {
        self.attributes.get(name)
            .and_then(|a| a.boilerplate.as_ref())
    }

    /// Check if an attribute requires a viewport client (viewport-specific)
    pub fn requires_client(&self, name: &str) -> bool {
        self.attributes.get(name)
            .map(|a| a.requires_client)
            .unwrap_or(false)
    }

    /// Get the client base class for viewport attributes
    pub fn get_client_base(&self, name: &str) -> Option<&str> {
        self.attributes.get(name)
            .map(|a| a.client_base.as_str())
            .filter(|s| !s.is_empty())
    }

    /// Get all attribute names
    pub fn attribute_names(&self) -> Vec<&str> {
        self.attributes.keys().map(|k| k.as_str()).collect()
    }

    /// Get count of registered attributes
    pub fn count(&self) -> usize {
        self.attributes.len()
    }

    /// Get examples for an attribute
    pub fn get_examples(&self, name: &str) -> Vec<&ExampleInfo> {
        self.attributes.get(name)
            .map(|a| a.examples.iter().collect())
            .unwrap_or_default()
    }

    /// Get the description for an attribute
    pub fn get_description(&self, name: &str) -> Option<&str> {
        self.attributes.get(name).map(|a| a.description.as_str())
    }

    /// Get what code pattern an attribute generates
    pub fn get_generates(&self, name: &str) -> Option<&str> {
        self.attributes.get(name).map(|a| a.generates.as_str())
    }
}

// ═══════════════════════════════════════════════════════════════════
// Tests
// ═══════════════════════════════════════════════════════════════════

#[cfg(test)]
mod tests {
    use super::*;

    fn sample_registry_json() -> &'static str {
        r#"{
            "_meta": {
                "generator": "editor_attributes_extractor.py",
                "source": "D:\\Unreal\\UE_5.7\\Engine\\Source",
                "total_attributes": 3,
                "description": "Test data"
            },
            "attributes": {
                "slate": {
                    "description": "Generates a Slate UI widget",
                    "base_class": "SCompoundWidget",
                    "class_prefix": "S",
                    "generates": "slate_widget",
                    "required_includes": ["Widgets/SCompoundWidget.h"],
                    "required_modules": ["Slate", "SlateCore"],
                    "examples": [],
                    "naming_convention": {
                        "prefix": "S",
                        "pattern": "S{Name}"
                    },
                    "boilerplate": {
                        "slate_begin_args": true,
                        "slate_end_args": true,
                        "construct_method": true
                    }
                },
                "details": {
                    "description": "Generates a Details panel customization",
                    "base_class": "IDetailCustomization",
                    "class_prefix": "F",
                    "class_suffix": "DetailsCustomization",
                    "generates": "details_customization",
                    "required_includes": ["IDetailCustomization.h"],
                    "required_modules": ["PropertyEditor"],
                    "examples": []
                },
                "viewport": {
                    "description": "Generates an editor viewport",
                    "base_class": "SEditorViewport",
                    "class_prefix": "S",
                    "class_suffix": "Viewport",
                    "generates": "editor_viewport",
                    "required_includes": ["SEditorViewport.h"],
                    "required_modules": ["UnrealEd"],
                    "requires_client": true,
                    "client_base": "FEditorViewportClient",
                    "client_prefix": "F",
                    "client_suffix": "ViewportClient",
                    "examples": []
                }
            }
        }"#
    }

    #[test]
    fn test_load_and_query() {
        let mut reg = EditorAttributesRegistry::new();
        reg.load(sample_registry_json()).unwrap();

        assert_eq!(reg.count(), 3);
        assert!(reg.is_editor_attribute("slate"));
        assert!(reg.is_editor_attribute("details"));
        assert!(reg.is_editor_attribute("viewport"));
        assert!(!reg.is_editor_attribute("unknown"));
    }

    #[test]
    fn test_base_class_lookup() {
        let mut reg = EditorAttributesRegistry::new();
        reg.load(sample_registry_json()).unwrap();

        assert_eq!(reg.get_base_class("slate"), Some("SCompoundWidget"));
        assert_eq!(reg.get_base_class("details"), Some("IDetailCustomization"));
        assert_eq!(reg.get_base_class("viewport"), Some("SEditorViewport"));
    }

    #[test]
    fn test_prefix_suffix() {
        let mut reg = EditorAttributesRegistry::new();
        reg.load(sample_registry_json()).unwrap();

        assert_eq!(reg.get_class_prefix("slate"), Some("S"));
        assert_eq!(reg.get_class_prefix("details"), Some("F"));
        assert_eq!(reg.get_class_suffix("details"), Some("DetailsCustomization"));
        assert_eq!(reg.get_class_suffix("viewport"), Some("Viewport"));
    }

    #[test]
    fn test_required_modules() {
        let mut reg = EditorAttributesRegistry::new();
        reg.load(sample_registry_json()).unwrap();

        let slate_modules = reg.get_required_modules("slate");
        assert_eq!(slate_modules, vec!["Slate", "SlateCore"]);

        let details_modules = reg.get_required_modules("details");
        assert_eq!(details_modules, vec!["PropertyEditor"]);
    }

    #[test]
    fn test_viewport_client() {
        let mut reg = EditorAttributesRegistry::new();
        reg.load(sample_registry_json()).unwrap();

        assert!(reg.requires_client("viewport"));
        assert!(!reg.requires_client("slate"));
        assert_eq!(reg.get_client_base("viewport"), Some("FEditorViewportClient"));
    }

    #[test]
    fn test_boilerplate_flags() {
        let mut reg = EditorAttributesRegistry::new();
        reg.load(sample_registry_json()).unwrap();

        let slate_boilerplate = reg.get_boilerplate("slate").unwrap();
        assert!(slate_boilerplate.slate_begin_args);
        assert!(slate_boilerplate.slate_end_args);
        assert!(slate_boilerplate.construct_method);
    }

    #[test]
    fn test_attribute_names() {
        let mut reg = EditorAttributesRegistry::new();
        reg.load(sample_registry_json()).unwrap();

        let mut names = reg.attribute_names();
        names.sort();
        assert_eq!(names, vec!["details", "slate", "viewport"]);
    }
}
